import{_ as r,C as s,c as a,o as i,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Manage opportunities","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/manage-opportunities.md","filePath":"master/sales/crm/pipeline/manage-opportunities.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/pipeline/manage-opportunities.md"};function g(h,t,d,p,u,c){const o=s("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="manage-opportunities" tabindex="-1">Manage opportunities <a class="header-anchor" href="#manage-opportunities" aria-label="Permalink to &quot;Manage opportunities&quot;">​</a></h1><p>An opportunity is a deal you are working on with a customer. It records what you hope to earn, how likely you are to win, and when you expect to close. The pipeline shows every opportunity, so you see at a glance what needs attention.</p><blockquote><p><strong>In simple words:</strong> An opportunity is one possible sale. You keep its details up to date until you win or lose it.</p></blockquote><p>Open <code>CRM → Sales → My Pipeline</code>. The page title is <strong>Opportunities</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Two fields appear only when a setting is on. Go to <code>CRM → Settings → Manage CRM</code>.</p><ul><li><strong>Recurring Revenue Plans:</strong> shows <strong>Recurring Revenue</strong> and <strong>Recurring Plan</strong> on the form. See <a href="./../configuration/recurring-plans.html">Recurring plans</a>.</li><li><strong>Lead Qualification:</strong> adds a lead step before an opportunity exists. See <a href="./../acquire-leads/convert-lead.html">Convert a lead</a>.</li></ul><h2 id="the-opportunity-pages" tabindex="-1">The opportunity pages <a class="header-anchor" href="#the-opportunity-pages" aria-label="Permalink to &quot;The opportunity pages&quot;">​</a></h2><p>The page has three layouts: <strong>Kanban</strong>, <strong>List</strong> and <strong>Graph</strong>. Switch between them with the layout buttons. It opens in Kanban.</p>',9)),n(o,{src:"/images1/crm/pipeline-kanban.png",alt:"Opportunities Kanban view of My Pipeline with the New, Qualified, Proposition and Won columns and the New Opportunity button"}),t[1]||(t[1]=e('<h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the board filter the records. The counts show how many records each tab holds.</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>All opportunities.</td></tr><tr><td><strong>My Pipeline</strong></td><td>Opportunities where you are the salesperson.</td></tr><tr><td><strong>Open</strong></td><td>Opportunities not yet in a won stage.</td></tr><tr><td><strong>Won</strong></td><td>Opportunities in a won stage.</td></tr><tr><td><strong>Lost</strong></td><td>Opportunities closed as lost.</td></tr><tr><td><strong>Unassigned</strong></td><td>Opportunities with no salesperson. Find it in the views menu.</td></tr></tbody></table><h3 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h3><p>Each column is a stage, such as <strong>New</strong>, <strong>Qualified</strong>, <strong>Proposition</strong> and <strong>Won</strong>. Won stages have a green header.</p><ul><li><strong>Column header.</strong> It shows the stage name and the total <strong>Expected Revenue</strong> of its cards.</li><li><strong>Activity bar.</strong> A coloured bar counts overdue, today, planned and unplanned deals. Click a colour to show only those cards.</li><li><strong>+ button.</strong> It opens <strong>Quick create opportunity</strong>. Fill in the <strong>Opportunity</strong> name, <strong>Customer</strong>, <strong>Expected Revenue</strong> and <strong>Priority</strong>. The deal lands in that stage.</li><li><strong>Settings menu.</strong> Choose <strong>Edit</strong> to rename the stage or <strong>Delete</strong> to remove it. A stage that still has deals cannot be deleted. Move its cards first.</li><li><strong>Add Stage.</strong> The button at the end of the board adds a new column.</li></ul><p>Each card shows:</p><ul><li>the opportunity name;</li><li>the expected revenue, plus the recurring revenue and plan when you use them;</li><li>the customer, or the contact name when no customer is set;</li><li>tags;</li><li>priority stars. Click a star to set the priority. Click the same star again to go back to <strong>Low</strong>;</li><li>a clock button for activities. It is red when overdue, orange when due today and green when planned;</li><li>a colour dot and the salesperson;</li><li>a <strong>Won</strong> or <strong>Lost</strong> label once the deal is closed.</li></ul><p>Open the card menu to choose <strong>Edit</strong>, <strong>Color</strong> or <strong>Delete</strong>. Click the card to open the opportunity.</p><p>Drag a card to another column to change its stage. Cards in the <strong>Lost</strong> tab cannot be moved. Restore them first.</p><h3 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h3><p>The list has these columns.</p><ul><li>Shown by default: <strong>Opportunity</strong>, <strong>Customer</strong>, <strong>Stage</strong>, <strong>Expected Revenue</strong>, <strong>Probability</strong>, <strong>Priority</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Expected Closing</strong> and <strong>Tags</strong>.</li><li>You can hide <strong>Expected Closing</strong> and <strong>Tags</strong> from the column menu.</li><li>Hidden by default: <strong>Recurring Revenue</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>Medium</strong>, <strong>Lost Reason</strong>, <strong>Created At</strong>. Show them from the column menu.</li></ul><p>The list sorts by <strong>Created At</strong>, newest first.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li><strong>Search.</strong> Type in the search box to match the opportunity name, customer or email.</li><li><strong>Filter.</strong> Build rules on <strong>Opportunity</strong>, <strong>Customer</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>Stage</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Tags</strong>, <strong>Priority</strong>, <strong>Source</strong>, <strong>Medium</strong>, <strong>Campaign</strong>, <strong>Country</strong>, <strong>Lost Reason</strong>, <strong>Expected Revenue</strong>, <strong>Probability</strong>, <strong>Expected Closing</strong> and <strong>Created At</strong>.</li><li><strong>Group by.</strong> Choose <strong>Stage</strong>, <strong>Sales Team</strong>, <strong>Salesperson</strong>, <strong>Priority</strong> or <strong>Expected Closing</strong>. The Graph layout charts the same groups.</li><li><strong>Export and import.</strong> Click <strong>Export</strong> to download the records you see. Click <strong>Import</strong> to load a file of opportunities.</li></ul><p>For general help, see <a href="./../../../getting-started/search-filter-group.html">Search, filter and group</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Select rows in the list to use bulk actions: <strong>Export</strong>, <strong>Restore</strong>, <strong>Delete</strong>, <strong>Force delete</strong>, <strong>Mark Lost</strong>, <strong>Merge</strong>, <strong>Send email</strong> and <strong>Send SMS</strong>.</p></div><h2 id="create-an-opportunity" tabindex="-1">Create an opportunity <a class="header-anchor" href="#create-an-opportunity" aria-label="Permalink to &quot;Create an opportunity&quot;">​</a></h2><p>Example: A salesperson records a chance with Sharma Textiles.</p><ol><li>Go to <code>CRM → Sales → My Pipeline</code>.</li><li>Click <strong>New Opportunity</strong>.</li></ol>',21)),n(o,{src:"/images1/crm/opportunity-create-form.png",alt:"New Opportunity form filled for Annual ERP licence - Sharma Textiles"}),t[2]||(t[2]=e('<ol start="3"><li>Fill in the form. The stage bar at the top shows every stage. The first stage is chosen for you.</li></ol><h3 id="stage" tabindex="-1">Stage <a class="header-anchor" href="#stage" aria-label="Permalink to &quot;Stage&quot;">​</a></h3><ul><li><strong><em>Stage:</em></strong> Where the deal starts. Required. The default is the first stage. Click another stage in the bar to change it.</li></ul><h3 id="opportunity" tabindex="-1">Opportunity <a class="header-anchor" href="#opportunity" aria-label="Permalink to &quot;Opportunity&quot;">​</a></h3><ul><li><strong><em>Opportunity:</em></strong> The name of the deal. Required, up to 255 characters. The hint reads &quot;e.g. Product Pricing&quot;.</li><li><strong><em>Expected Revenue:</em></strong> The amount you hope to earn. The default is 0. It cannot be negative.</li><li><strong><em>Probability:</em></strong> Your chance of winning, from 0 to 100%. Leave it empty to show <strong>Automatic</strong>, which uses lead scoring. See <a href="./../assign-and-track/lead-scoring.html">Lead scoring</a>.</li><li><strong><em>Recurring Revenue:</em></strong> The amount that repeats each period. Shown only when <strong>Recurring Revenue Plans</strong> is on. The default is 0.</li><li><strong><em>Recurring Plan:</em></strong> How often it repeats, such as <strong>Monthly</strong> or <strong>Yearly</strong>. Required when <strong>Recurring Revenue</strong> is above 0.</li><li><strong><em>Customer:</em></strong> The company or person you sell to. Search for it. Choosing one fills <strong>Email</strong> and <strong>Phone</strong> for you.</li><li><strong><em>Email:</em></strong> The contact email.</li><li><strong><em>Phone:</em></strong> The contact phone number.</li></ul><h3 id="internal-notes" tabindex="-1">Internal Notes <a class="header-anchor" href="#internal-notes" aria-label="Permalink to &quot;Internal Notes&quot;">​</a></h3><ul><li><strong><em>Internal Notes:</em></strong> A text box for your team. The customer does not see it.</li></ul><h3 id="sales" tabindex="-1">Sales <a class="header-anchor" href="#sales" aria-label="Permalink to &quot;Sales&quot;">​</a></h3><ul><li><strong><em>Salesperson:</em></strong> The owner of the deal. The default is you.</li><li><strong><em>Sales Team:</em></strong> The team that handles it. This feeds the team cards.</li><li><strong><em>Company:</em></strong> Your company that owns the deal. The default is the current company.</li><li><strong><em>Expected Closing:</em></strong> The date you expect to close. Use it for the forecast.</li><li><strong><em>Priority:</em></strong> <strong>Low</strong>, <strong>Medium</strong>, <strong>High</strong> or <strong>Very High</strong>. The default is <strong>Low</strong>.</li><li><strong><em>Tags:</em></strong> Labels such as <strong>Software</strong> or <strong>Upsell</strong>. You can create a tag from this field.</li></ul><p><strong>Example:</strong> Name <code>Annual ERP licence - Sharma Textiles</code>, Expected Revenue <code>1850000</code>, Recurring Revenue <code>240000</code> with Recurring Plan <strong>Yearly</strong>, Customer <code>Sharma Textiles</code>, Salesperson ERP Admin, Expected Closing <code>18 December 2026</code>, Priority <code>High</code>, Tag <code>Software</code>.</p><ol start="4"><li>Click <strong>Create</strong>. A notification says <strong>Opportunity created</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Customers live in Contacts. See <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p></div><h2 id="work-on-an-opportunity" tabindex="-1">Work on an opportunity <a class="header-anchor" href="#work-on-an-opportunity" aria-label="Permalink to &quot;Work on an opportunity&quot;">​</a></h2><p>Open a card or a list row. The page shows the details in read mode. Click the <strong>Edit</strong> tab to change them. The edit form has the same fields as above. A notification says <strong>Opportunity updated</strong> when you save.</p><p>The page tabs are:</p><ul><li><strong>Activities:</strong> planned calls and meetings, with a count. Click <strong>Schedule Activity</strong> here. See <a href="./schedule-activities.html">Schedule activities</a>.</li><li><strong>Quotations:</strong> offers made for this deal, with a count. See <a href="./create-quotation.html">Create a quotation</a>.</li><li><strong>Similar Opportunities:</strong> other leads or opportunities with the same email, phone or customer. You can merge them.</li></ul><p>The <strong>Chatter</strong> button opens notes, messages and files. See <a href="./../../../getting-started/chatter/introduction.html">Chatter</a>.</p>',17)),n(o,{src:"/images1/crm/opportunity-view.png",alt:"Opportunity page for Annual ERP licence - Sharma Textiles with the header buttons, tabs and stage bar"}),t[3]||(t[3]=e('<h3 id="probability-details" tabindex="-1">Probability details <a class="header-anchor" href="#probability-details" aria-label="Permalink to &quot;Probability details&quot;">​</a></h3><p>Next to <strong>Probability</strong> are two small actions on the edit form.</p><ul><li><strong>Probability details</strong> shows the computed probability and the sales team used.</li><li><strong>Use computed probability</strong> drops your manual value and returns to <strong>Automatic</strong>.</li></ul><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Chatter</strong></td><td>Opens notes, messages and files for the record.</td></tr><tr><td><strong>New Quotation</strong></td><td>Starts a quotation for this opportunity.</td></tr><tr><td><strong>Won</strong></td><td>Moves the deal to the won stage.</td></tr><tr><td><strong>Lost</strong></td><td>Closes the deal as lost, with a reason.</td></tr><tr><td><strong>Send email</strong></td><td>Emails the contact. Needs an email address.</td></tr><tr><td><strong>Send SMS</strong></td><td>Sends a text to the contact.</td></tr><tr><td><strong>Delete</strong></td><td>Deletes the opportunity.</td></tr><tr><td><strong>Restore</strong></td><td>Brings a lost opportunity back to the pipeline.</td></tr></tbody></table><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Stage change.</strong> Moving a card, or choosing a stage, updates the stage at once.</li><li><strong>Probability.</strong> Entering a value switches off <strong>Automatic</strong>. A won stage sets 100%.</li><li><strong>Closed date.</strong> Winning or losing stores the date as <strong>Closed At</strong>. It shows in the <strong>Sales</strong> section.</li><li><strong>Quotation link.</strong> Quotations made here appear on the <strong>Quotations</strong> tab.</li><li><strong>Assignment date.</strong> Changing the salesperson stores the date of assignment.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./mark-won-lost.html">Mark an opportunity won or lost</a></li><li><a href="./../configuration/stages.html">Stages</a></li><li><a href="./../acquire-leads/convert-lead.html">Convert a lead</a></li><li><a href="./manage-sales-teams.html">Manage sales teams</a></li></ul>',9))])}const y=r(l,[["render",g]]);export{b as __pageData,y as default};
